1	package clinical
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	// dataName 是存放全部业务状态的快照文件名。
15	const dataName = "clinical-data.json"
16	
17	// dataVersion 是快照格式的版本标记，便于将来迁移。
18	const dataVersion = 1
19	
20	// snapshot 是写入磁盘的完整状态。所有业务对象集中在一个文件中，
21	// 采用“临时文件 + 原子改名”整体落盘：成功操作与其审计事件一同保留，
22	// 失败的操作在 mutate 中就已丢弃，不会写出半截状态。
23	type snapshot struct {
24		FormatVersion  int                       `json:"format_version"`
25		Patients       map[string]*Patient       `json:"patients"`
26		Encounters     map[string]*Encounter     `json:"encounters"`
27		Records        map[string]*Record        `json:"records"`
28		Versions       map[string]*Version       `json:"versions"`
29		Authorizations map[string]*Authorization `json:"authorizations"`
30		AuditEvents    []*AuditEvent             `json:"audit_events"`
31	}
32	
33	// Clock 决定“发生时间”的来源。生产使用实时时钟；测试可注入固定/可控时钟
34	// 以验证开始、到期、撤回等时间边界。
35	type Clock func() time.Time
36	
37	// Store 是本地临床档案的句柄。数据存放位置由调用方在 Open 时指定。
38	// 同一目录同一时刻只允许一个 Store 打开（通过锁文件互斥）。
39	type Store struct {
40		dir   string
41		clock Clock
42		mu    sync.Mutex
43		lock  *os.File
44		data  *snapshot
45	}
46	
47	// Option 配置 Open 的行为。
48	type Option func(*Store)
49	
50	// WithClock 注入自定义时钟。
51	func WithClock(c Clock) Option {
52		return func(s *Store) { s.clock = c }
53	}
54	
55	// Open 在指定目录打开（必要时创建）本地存储。
56	// 调用方指定数据存放位置；关闭后从同一位置重新打开可看到全部历史，
57	// 到期与否始终按“本次读取时间”重新计算。
58	func Open(dir string, opts ...Option) (*Store, error) {
59		if dir == "" {
60			return nil, fmt.Errorf("%w: empty data directory", ErrInvalidArgument)
61		}
62		if err := os.MkdirAll(dir, 0o755); err != nil {
63			return nil, err
64		}
65	
66		lockPath := filepath.Join(dir, ".clinical.lock")
67		lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
68		if err != nil {
69			return nil, err
70		}
71		if err := tryLockFile(lockFile); err != nil {
72			lockFile.Close()
73			return nil, err
74		}
75	
76		s := &Store{dir: dir, clock: time.Now, lock: lockFile}
77		for _, opt := range opts {
78			opt(s)
79		}
80		if s.clock == nil {
81			s.clock = time.Now
82		}
83	
84		if err := s.loadLocked(); err != nil {
85			unlockFile(lockFile)
86			lockFile.Close()
87			return nil, err
88		}
89		return s, nil
90	}
91	
92	func (s *Store) loadLocked() error {
93		path := filepath.Join(s.dir, dataName)
94		raw, err := os.ReadFile(path)
95		if os.IsNotExist(err) {
96			s.data = newSnapshot()
97			return nil
98		}
99		if err != nil {
100			return err
101		}
102		var snap snapshot
103		if err := json.Unmarshal(raw, &snap); err != nil {
104			return err
105		}
106		if snap.FormatVersion != dataVersion {
107			return fmt.Errorf("clinical: unsupported data format version %d", snap.FormatVersion)
108		}
109		ensureMaps(&snap)
110		s.data = &snap
111		return nil
112	}
113	
114	func newSnapshot() *snapshot {
115		snap := &snapshot{FormatVersion: dataVersion}
116		ensureMaps(snap)
117		return snap
118	}
119	
120	func ensureMaps(snap *snapshot) {
121		if snap.Patients == nil {
122			snap.Patients = map[string]*Patient{}
123		}
124		if snap.Encounters == nil {
125			snap.Encounters = map[string]*Encounter{}
126		}
127		if snap.Records == nil {
128			snap.Records = map[string]*Record{}
129		}
130		if snap.Versions == nil {
131			snap.Versions = map[string]*Version{}
132		}
133		if snap.Authorizations == nil {
134			snap.Authorizations = map[string]*Authorization{}
135		}
136	}
137	
138	// Close 刷新并释放数据目录。Close 后任何业务方法返回 ErrClosed。
139	func (s *Store) Close() error {
140		s.mu.Lock()
141		defer s.mu.Unlock()
142		if s.lock == nil {
143			return ErrClosed
144		}
145		unlockFile(s.lock)
146		err := s.lock.Close()
147		if rmErr := os.Remove(filepath.Join(s.dir, ".clinical.lock")); rmErr != nil && !os.IsNotExist(rmErr) && err == nil {
148			err = rmErr
149		}
150		s.lock = nil
151		s.data = nil
152		return err
153	}
154	
155	func (s *Store) now() time.Time { return s.clock().UTC() }
156	
157	// mutate 在状态的深拷贝上执行业务变更。fn 返回错误时，拷贝连同其中的
158	// 半成品一并丢弃，磁盘与既有业务状态保持原样；fn 返回 nil 时整体原子落盘。
159	// 这样“引用不存在的对象/跨患者混用”等失败都不会留下半条记录。
160	func (s *Store) mutate(fn func(*snapshot) error) error {
161		s.mu.Lock()
162		defer s.mu.Unlock()
163		if s.data == nil {
164			return ErrClosed
165		}
166	
167		clone := cloneSnapshot(s.data)
168		if err := fn(clone); err != nil {
169			return err
170		}
171		if err := s.persist(clone); err != nil {
172			return err
173		}
174		s.data = clone
175		return nil
176	}
177	
178	// view 在只读快照上执行查询。
179	func (s *Store) view(fn func(*snapshot) error) error {
180		s.mu.Lock()
181		defer s.mu.Unlock()
182		if s.data == nil {
183			return ErrClosed
184		}
185		return fn(s.data)
186	}
187	
188	func (s *Store) persist(snap *snapshot) error {
189		raw, err := json.MarshalIndent(snap, "", "  ")
190		if err != nil {
191			return err
192		}
193		final := filepath.Join(s.dir, dataName)
194		tmp := filepath.Join(s.dir, dataName+".tmp")
195		if err := os.WriteFile(tmp, raw, 0o600); err != nil {
196			return err
197		}
198		if err := os.Rename(tmp, final); err != nil {
199			_ = os.Remove(tmp)
200			return err
201		}
202		return nil
203	}
204	
205	func cloneSnapshot(in *snapshot) *snapshot {
206		out := &snapshot{
207			FormatVersion:  in.FormatVersion,
208			Patients:       make(map[string]*Patient, len(in.Patients)),
209			Encounters:     make(map[string]*Encounter, len(in.Encounters)),
210			Records:        make(map[string]*Record, len(in.Records)),
211			Versions:       make(map[string]*Version, len(in.Versions)),
212			Authorizations: make(map[string]*Authorization, len(in.Authorizations)),
213			AuditEvents:    make([]*AuditEvent, 0, len(in.AuditEvents)),
214		}
215		for k, v := range in.Patients {
216			p := *v
217			out.Patients[k] = &p
218		}
219		for k, v := range in.Encounters {
220			e := *v
221			out.Encounters[k] = &e
222		}
223		for k, v := range in.Records {
224			r := *v
225			r.Versions = append([]ID(nil), v.Versions...)
226			out.Records[k] = &r
227		}
228		for k, v := range in.Versions {
229			vv := *v
230			out.Versions[k] = &vv
231		}
232		for k, v := range in.Authorizations {
233			a := *v
234			a.Scopes = append([]Scope(nil), v.Scopes...)
235			if v.RevokedAt != nil {
236				t := *v.RevokedAt
237				a.RevokedAt = &t
238			}
239			out.Authorizations[k] = &a
240		}
241		for _, ev := range in.AuditEvents {
242			e := *ev
243			out.AuditEvents = append(out.AuditEvents, &e)
244		}
245		return out
246	}
247	
248	func newID(prefix string) string {
249		var b [12]byte
250		if _, err := rand.Read(b[:]); err != nil {
251			// crypto/rand 失败在正常运行环境中不应发生；无法安全生成标识时直接中断。
252			panic(fmt.Errorf("clinical: cannot generate id: %w", err))
253		}
254		return prefix + "_" + hex.EncodeToString(b[:])
255	}
256	
257	func (s *Store) addAudit(snap *snapshot, patientID ID, actor Actor, action, objectType, objectID ID, at time.Time) {
258		snap.AuditEvents = append(snap.AuditEvents, &AuditEvent{
259			ID:         newID("aud"),
260			PatientID:  patientID,
261			ActorID:    actor.ID,
262			Action:     action,
263			ObjectType: objectType,
264			ObjectID:   objectID,
265			OccurredAt: at,
266		})
267	}
