483		v2, _ := s.CorrectRecord(doc, rec.ID, 1, "v2", "原因A")
484	
485		// 授权：在当前窗口内有效，但未来会到期。
486		grantStart := clk.t.Add(-time.Hour)
487		grantEnd := clk.t.Add(2 * time.Hour)
488		a, _ := s.Grant(doc, p.ID, rcv.ID, []Scope{{EncounterID: e.ID, Category: Diagnosis}}, grantStart, grantEnd)
489		_ = v1
490		if err := s.Close(); err != nil {
