536		}
537		if _, err := s2b.Read(rcv, p.ID, e.ID, Diagnosis); !errors.Is(err, ErrAccessDenied) {
538			t.Fatalf("revoked grant must deny after reopen: %v", err)
539		}
540		// 重开后重复撤回仍幂等。
541		rn1 := len(mustAudit(t, s2b, p.ID))
542		if err := s2b.Revoke(doc, p.ID, a.ID); err != nil {
543			t.Fatal(err)
