545		if rn2 := len(mustAudit(t, s2b, p.ID)); rn2 != rn1 {
546			t.Fatalf("idempotent revoke after reopen added events: %d -> %d", rn1, rn2)
547		}
548		if err := s2b.Close(); err != nil {
549			t.Fatal(err)
550		}
