// EffectiveRecord 是对外暴露的一条当前生效记录。
type EffectiveRecord struct {
	RecordID    ID
	VersionID   ID
	Version     int
	Content     string
	EffectiveAt time.Time
}

// ExchangeRecord 是封入交换包的一条记录在创建时刻的固化内容：
// 就诊、类别、记录与版本标识、版本号、生效时间与完整内容。
// 不含姓名、草稿、其他历史版本或更正原因。
type ExchangeRecord struct {
	EncounterID ID
	Category    string
	RecordID    ID
	VersionID   ID
	Version     int
	EffectiveAt time.Time
	Content     string
}

// ExchangePackage 是交换的密封内容：只含患者与接收方标识，
// 以及各记录在创建时刻的当前版本快照。
type ExchangePackage struct {
	PatientID  ID
	ReceiverID string
	Records    []ExchangeRecord // 按记录标识升序排列
}

